prepareCalculators = {
// which calculators share which preparation (the 3 Check buttons share recalc package)
const groups = {
  statcheck:{
  // write a function with no arguments using =&gt;, it is stored and run yet, will be called later when calculator in view
  // statcheckR.get(), webRSession.load("metafor"), recalcR.get(): all Ian's own functions, just install
  // This code calls the above earlier than a click would
  // watch when it scrolls into view and find its button so put the status next to it
  prepare: () =&gt; statcheckR.get(), inputs: [viewof scBatch], button: "Run statcheck"}, // viewof scBatch is calculator's box on page
  metafor: {prepare: () =&gt; webRSession.load("metafor"), inputs:[viewof smdInput], button: "Calculate SMDs"},
  recalc:{prepare: () =&gt; recalcR.get(), inputs: [viewof ttInput, viewof orInput, viewof sgInput], button: "Check"}
}
const messages = {
  preparing: `&lt;span class="spinner-border spinner-border-sm" aria-hidden="true"&gt;&lt;/span&gt; Preparing R, a few seconds…`,
  ready: `&lt;span aria-hidden="true"&gt;✓&lt;/span&gt; Ready to run`,
  failed: `&lt;span aria-hidden="true"&gt;!&lt;/span&gt; Couldn't prepare R. Please reload the page.`
}

// put an empty status next to each R button
for (const group of Object.values(groups)) {
  //  # find the R button in the box
  group.statuses = group.inputs.map(input =&gt; {
      const button = [...input.querySelectorAll("button")].find(b =&gt; b.textContent.trim() === group.button)
      const status = html`&lt;span class="prep-status" role="status" aria-live="polite"&gt;&lt;/span&gt;`
      button.parentElement.append(status) // put the label at the end of the button row, after the last button
      return status 
    })
}

// show: changes what the labels display
// start: begins a group's preparation and updates the labels as it goes
// goes through each label of the group and runs the code for each
const show = (group, state) =&gt; group.statuses.forEach(status =&gt; {
    // sets the label's CSS classes, which controls its color
    status.className = `prep-status prep-${state}`
    status.innerHTML = messages[state] // sets what the label displays (message), it contains spinner element, so innerHTML used
})

//start: begin preparing a group
const start = group =&gt; {
  if (group.started) return // if this group has already been started, stop there. return exists the function.
  group.started = true
  show(group, "preparing")
  group.prepare().then(() =&gt; show(group, "ready"), () =&gt; show(group, "failed"))
}

// start a group as soon as one of its calculators comes within 300px of the screen
// entries: what the browser calls each time something it watches changes visibility. 
// callback: 'call me back when it happens'
// entries: list of reports, one per page element whose visibility changed.
const observer = new IntersectionObserver(entries =&gt; { // created a watcher and stored as 'observer'
  for (const entry of entries) {
    // if the element is now in (or near) view
    if (!entry.isIntersecting) continue // if this cal. just scrolled away, ignore it, only act when one arrives
    // finds which group this cal. belongs to
    // entry.target: is the element that triggered the report, one of the calculator boxes
    const group = Object.values(groups).find(g =&gt; g.inputs.includes(entry.target))
    // tell watcher to stop watching all boxes of this group. 
    // A group only needs to start once, so no point getting more reports
    group.inputs.forEach(input =&gt; observer.unobserve(input))
    start(group)
    }
}, 
// setting for watcher
// enlarging the 'visible area' by 300 pixels above and below the screen
{rootMargin: "300px 0px"})
// observer.observe(input) goes through every group and every calculator box and tells the watcher “watch this one”.
// Without this line, the watcher would exist but watch nothing.
// (It’s written after the callback, but it’s what actually switches the watching on.)
Object.values(groups).forEach(group =&gt; group.inputs.forEach(input =&gt; observer.observe(input)))
  // invalidation is an OJS built-in: a promise that’s settled when this cell is re-run or removed.
  // When that happens, observer.disconnect() stops all watching, so an old watcher doesn’t keep running in the background. It’s housekeeping.
  invalidation.then(() =&gt; observer.disconnect())
  // status pill: rounded, soft tinted background, darker text and border in the same colour
  return html`&lt;style&gt;
    .prep-status { display: inline-flex; align-items: center; gap: 0.4rem; margin-left: 0.25rem;
      padding: 0.25rem 0.75rem; border: 1px solid transparent; border-radius: 999px;
      font-size: 0.85rem; font-weight: 500; line-height: 1.3;
      transition: background-color 0.3s, color 0.3s, border-color 0.3s; }
    .prep-status:empty { display: none; }
    .prep-status .spinner-border { width: 0.8rem; height: 0.8rem; border-width: 0.15em; }
    .prep-preparing { background: #eaf2fd; color: #1f6ab8; border-color: #c6dcf8; }
    .prep-ready { background: #e8f5e9; color: #2e7d32; border-color: #c3e4c5; }
    .prep-failed { background: #fdecea; color: #c62828; border-color: #f5c4bf; }
    /* while the pill says "Preparing", hide Ian's loading line (the status with a spinner) in the same section */
    section:has(.prep-preparing) .sc-status:has(&gt; .spinner-border) { display: none; }
  &lt;/style&gt;`
}

